	'topics'     => array(
		array( 'announcements', 10, 'Welcome to the community forums', 'This is the place for longer conversations than the feed allows. Start a discussion, ask a question, or suggest an idea. Please read the guidelines in the pinned post and be kind.', array( 'Glad to be here. The space cards make it easy to find where to post.', 'Thanks for setting this up. Is there a space for off-topic chat?', 'Yes, The Lounge in the community spaces is the place for that.', 'Read the guidelines, all clear. Looking forward to it.', 'Hello everyone, first post from me!', 'Nice and tidy. The accepted answers will save a lot of repeat questions.' ), false ),
		array( 'announcements', 2, 'Community call recap: what we decided', 'Thanks to everyone who joined. We agreed on monthly critique sessions, a mentoring pilot for new members and a quiet hour each Friday. Notes are below, add anything we missed.', array( 'Thanks for the recap, I missed the call.', 'Monthly feels right. Weekly would be too much for most of us.', 'Can we get the recording link in the next recap too?', 'Happy with the moderation changes, clear and fair.' ), false ),
		array( 'introduce-yourself', 16, 'Hi from Lyon, junior developer here', 'Six months into my first developer job. I mostly write JavaScript and I am trying to get better at testing. Happy to be here!', array( 'Bienvenue! Lyon has a lovely meetup scene, you will find people fast.', 'Welcome! Help and Questions is the best place to start.', 'Junior to junior: ask everything, nobody minds here.', 'What stack are you working in?', 'Mostly Vue and a bit of PHP for now.', 'Then the CSS structure thread will be useful to you.', 'Welcome aboard!' ), false ),
		array( 'introduce-yourself', 13, 'Brand designer from Porto', 'I design logos and packaging, mostly for small food brands. Looking for people to swap feedback with.', array( 'Welcome! Would love to see your work in Show and Tell.', 'Porto is on my list. Any coffee tips for a visitor?', 'Another designer here, say hello in the design space.', 'Do you do mostly identity work or packaging too?', 'Mostly identity, some packaging for local wineries.' ), false ),
		array( 'introduce-yourself', 19, 'Mobile developer in Accra', 'I build Android and iOS apps that have to work on slow networks. Ask me anything about offline-first.', array( 'Welcome! Kotlin or Flutter?', 'Kotlin mostly, some Flutter for side projects.', 'Accra has a great dev community, good to have you here.', 'The mobile-first thread in Career Corner is worth a read.' ), false ),
		array( 'help-and-questions', 16, 'How do you structure CSS in a large project?', 'Our stylesheet is 6,000 lines and every change breaks something. Do you use layers, BEM, utility classes? What actually worked for you?', array( 'We moved to one file per component and it fixed most of our merge conflicts.', 'Utility classes for spacing and layout, components for everything else. Works for a team of eight.', 'Name things after what they are, not how they look. Saves you on every redesign.', 'Have you tried cascade layers? They took most of the specificity fights away for us.', 'BEM still works fine if everyone sticks to it.', 'Whatever you pick, write it down. A one-page guide matters more than the method.' ), 'Use cascade layers for the big buckets (reset, base, components, utilities) and keep component styles next to the component. It took us a sprint to migrate and the breakages stopped.' ),
		array( 'help-and-questions', 5, 'Best way to learn pixel art animation?', 'I can draw a static sprite but walking cycles look stiff. Any courses or exercises you would recommend?', array( 'Start with a bouncing ball, then a walk cycle. Everything else builds on those two.', 'Keep the palette tiny at first, four colours. It forces you to think about shapes.', 'Aseprite is worth the money for the onion skinning alone.', 'Copy frame by frame from games you love. It is how most of us learned.' ), 'Do the classic exercise: animate a bouncing ball in four frames, then eight. Once timing clicks, walking cycles get much easier.' ),
		array( 'help-and-questions', 18, 'How do you say no to feature requests politely?', 'We get dozens of requests a week from good customers. I want to say no without sounding like we do not care.', array( 'We send a short monthly update to everyone who asked. Saying no feels easier when they can see what we chose instead.', 'Thank them for the detail first. Most people just want to know someone read it.', 'A public roadmap helped us a lot. We point people to it instead of writing a new no each time.', 'Say not now instead of never when it is true. It keeps the door open without promising anything.', 'If the same request comes three times, we look at it again. Telling people that makes the no land softer.' ), 'Thank them, say what you are focused on instead and why, and tell them where to follow progress. People mostly want to be heard.' ),
		array( 'help-and-questions', 3, 'Which font licence do I need for a client logo?', 'The client wants to use a typeface I licensed for my portfolio in their logo. Is a desktop licence enough?', array( 'Read the foundry terms first, logo use is often excluded from desktop licences.', 'Most foundries sell a logo licence for a one-off fee. Ask them, they answer quickly.', 'Or pick an open licence font for the logo and keep the paid one for the rest of the brand.' ), 'Usually no. Logos need a specific logo or extended licence. Check the foundry terms or ask them directly, most are friendly about it.' ),
		array( 'help-and-questions', 11, 'Soldering iron recommendations for beginners?', 'Building my first synth kit. Is a cheap iron fine or will it ruin the board?', array( 'A cheap iron with temperature control is fine. Avoid the ones without it.', 'Get a fine chisel tip and some flux, they matter more than the iron.', 'Practice on an old board first. Ten joints and you will see the difference.', 'And a fume fan, even a small one.' ), false ),
		array( 'show-and-tell', 0, 'Redesigned our onboarding: before and after', 'We cut onboarding from seven screens to three and moved account setup to after the first win. Completion went from 41% to 68%. Screens inside.', array( 'The before and after side by side makes the case instantly.', '41 to 68 percent is a huge jump. What did you cut first?', 'We merged profile and preferences into one screen and moved the rest to later.', 'Did support tickets go down as well?', 'About a third fewer in the first month.', 'Moving setup after the first win is such a good idea. Stealing it.', 'Did you test it with new users or just ship it?', 'Five user interviews, then shipped behind a flag.' ), false ),
		array( 'show-and-tell', 4, 'I charted every run from this year', 'A small data viz project: elevation, pace and mood for 140 runs. The mood axis is very scientific.', array( 'Those charts are lovely. What did you use to make them?', 'A spreadsheet export from my watch and a bit of D3.', 'The streak chart is motivating. I might copy the idea.', 'How many kilometres in total?', 'Just over 1,400. More than I thought.' ), false ),
		array( 'show-and-tell', 3, 'Finished my first typeface', 'Two years of evenings. It is a soft serif with 380 glyphs. Specimen and the story behind it inside.', array( 'The lowercase g is gorgeous.', 'How long did it take from first sketch to a usable font?', 'About nine months of evenings.', 'Are you releasing it for others to use?', 'Yes, under an open licence once the kerning is done.', 'Congratulations, a first typeface is a big deal.' ), false ),
		array( 'show-and-tell', 9, 'Street photography from one month in Seoul', 'Thirty frames, all shot with a 35mm lens and no editing beyond crop. Which one is your favourite?', array( 'The night shots in the market are my favourites.', 'What camera did you carry all month?', 'A small fixed-lens compact, so people barely noticed it.', 'Did you ask people before taking their photo?' ), false ),
		array( 'career-corner', 12, 'What we look for when hiring remote developers', 'I hire for a remote-first studio. Here is what actually makes a candidate stand out, and what does not matter as much as people think.', array( 'Clear written updates. If someone writes well, remote work is easy with them.', 'We look at how people ask questions in the trial task more than the code.', 'Time zone overlap of at least three hours matters more than people think.', 'Open source contributions tell us more than any test.', 'Do you pay the same rate for every location?', 'Same band for the same role, adjusted a little for cost of living.', 'Thanks for sharing this openly. Very helpful for job seekers.' ), false ),
		array( 'career-corner', 8, 'Moving from copywriting to UX writing', 'I made the switch two years ago. Here is the portfolio that got me hired and the mistakes I made along the way.', array( 'You already have the hardest skill: writing clearly for one reader.', 'Rewrite the error messages of an app you use and put them in a portfolio.', 'Learn a little about user research. It changes how you write.', 'I made the same move. It took me about six months.', 'Microcopy case studies got me my first interviews.' ), false ),
		array( 'career-corner', 16, 'How did you negotiate your first raise?', 'My review is next month. I have no idea how to bring up money. Any scripts that worked for you?', array( 'I wrote down three things I had shipped that year and led with those.', 'Ask for a number, not a range. Ranges get you the bottom of the range.', 'Practise the conversation out loud with a friend first.', 'If they say no, ask what you would need to show by next review.', 'I asked for 10 percent and got 8. Still the best email I ever sent.', 'Timing matters too: right after a big win is the moment.' ), false ),
		array( 'ideas', 17, 'Monthly in-person meetups in more cities', 'We have enough members in Lisbon, Berlin and Lagos to start small monthly meetups. I can help with the format.', array( 'Yes please! Lisbon would be a great next city.', 'I could help organise one in Manchester.', 'Maybe start with a shared calendar so people can see interest by city.' ), false ),
		array( 'ideas', 14, 'A mentoring programme for new members', 'Pair every new member with someone who has been here a while, for their first month. Light touch, one call a week.', array( 'Count me in as a mentor for frontend work.', 'Monthly calls with a clear goal would keep it from fading.', 'Pair a mentor with two people so nobody feels like a burden.', 'I would have loved this when I started.' ), false ),
		array( 'ideas', 1, 'Accessibility review swap', 'Members post a page and two others review it for accessibility, then swap. Learning and helping at once.', array( 'Great idea. I can review keyboard navigation in exchange.', 'Could we keep a checklist in the space so reviews are consistent?' ), false ),
		array( 'announcements', 2, 'Office hours move to every other Thursday', 'From next week, community office hours run every other Thursday at 17:00 UTC. Same link, same relaxed format. Bring a question or just listen in.', array( 'Thursday works much better for me, thanks.', 'Will these be recorded for other time zones?', 'Yes, recordings go in Events and Office Hours the next day.' ), false ),
		array( 'announcements', 10, 'Q&A spaces now show the accepted answer first', 'When a question has an accepted answer, it now sits right under the question. Thanks to everyone who asked for this in Site Feedback.', array( 'This saves me so much scrolling.', 'Small change, big difference. Nice one.' ), false ),
		array( 'introduce-yourself', 6, 'Ocean systems researcher saying hello', 'I study how coastal currents move heat around. Mostly Python and a lot of maps. Here to learn better data viz and meet people outside academia.', array( 'Welcome Amina! The data viz crowd here is great.', 'Would love to see some of your maps in Show and Tell.', 'Welcome aboard!' ), false ),
		array( 'career-corner', 19, 'Freelance or full-time for a first mobile job?', 'I have two offers: a six-month freelance contract with a startup or a full-time junior role at an agency. Which would you take first?', array( 'Full-time first. You learn faster with a team around you.', 'Depends on the startup. If they ship weekly, the freelance gig could teach more.', 'Whatever you pick, ask who will review your code.' ), false ),
		array( 'ideas', 15, 'A members-only job board', 'Members could post roles from their own companies and freelance gigs. Feels better than sending people to big job sites.', array( 'Yes please, I would post our next backend role here.', 'Could we tag remote and on-site roles?' ), false ),
		array( 'community-guidelines', 2, 'Community guidelines: the short version', 'Be kind, credit other people\'s work, keep promotion to Show and Tell, and ask before sending a private message. The full version is pinned below.', array( 'Clear and short. Thank you.', 'Love the bit about asking before a DM.' ), false ),
		array( 'community-guidelines', 2, 'How and when to use the flag button', 'Flag a post when it breaks the guidelines: spam, harassment, or personal details shared without consent. Disagreement is not a reason to flag.', array( 'Good to have this written down.', 'What if I flag by mistake?', 'No harm done. A moderator reviews every flag before anything happens.' ), false ),
		array( 'community-guidelines', 10, 'Our self-promotion policy, explained', 'Share your work in Show and Tell and your jobs in Career Corner. Links to your own product inside other threads are fine only when they answer the question.', array( 'Fair rules. Most communities get this wrong.', 'Thanks for keeping it simple.' ), false ),
		array( 'community-guidelines', 18, 'What happens after a post is flagged', 'A moderator looks at it within a day. If it breaks the guidelines it is hidden and the author gets a note explaining why. Repeat issues lead to a pause.', array( 'Appreciate the transparency.', 'A day is fast. Thank you, mods.' ), false ),
		array( 'getting-started', 16, 'Where should I post a beginner question?', 'I have a basic CSS question and I do not want to clutter the bigger discussions. Is there a right place?', array( 'Same question here when I joined.' ), 'Help and Questions is the right place, beginner or not. Ask there and someone will mark the answer that helped so the next person finds it.' ),
		array( 'getting-started', 19, 'How do I choose which emails I get?', 'I would like a weekly summary instead of an email for every reply.', array( 'Weekly summary is the way to go.' ), 'Open your profile, go to Settings, then Notifications. You can switch each kind of email off and keep the weekly summary on.' ),
		array( 'getting-started', 11, 'Can I edit a post after publishing?', 'I spotted a typo in my first topic right after posting it.', array( 'Happens to all of us.' ), 'Yes. Open the menu on your post and choose Edit. Small fixes are fine any time; if you change the meaning, add a short note at the end.' ),
		array( 'getting-started', 13, 'How do tags work here?', 'I see tags like Design and CSS under some topics. Do I need to add them?', array( 'Tags make search so much easier.' ), 'They are optional but helpful. Add one or two when you start a discussion, and click any tag to see every topic that uses it.' ),
		array( 'resources-and-tools', 1, 'The accessibility tools I use every day', 'A screen reader, a contrast checker, the browser accessibility tree and a keyboard-only hour every Friday. What is in your kit?', array( 'The keyboard-only hour is a great habit.', 'Adding the contrast checker to my list, thanks.', 'Do you test with more than one screen reader?' ), false ),
		array( 'resources-and-tools', 14, 'Free courses that are actually worth finishing', 'I build courses for a living, so I am picky. These five are short, practical and have exercises that make you think.', array( 'Saved. The design systems one looks great.', 'Finished the first one last night, it was excellent.' ), false ),
		array( 'resources-and-tools', 7, 'My terminal setup after ten years', 'Fewer plugins, better aliases. I removed half my setup last year and got faster. Here is what survived.', array( 'The git aliases alone are worth it.', 'Same journey here. Less is more.', 'Which shell are you on now?' ), false ),
		array( 'resources-and-tools', 13, 'Where I find fonts and images I can actually use', 'A short list of sources with clear licences for client work, and the questions I ask before using anything in a logo.', array( 'The licence questions are gold.', 'Bookmarked, thank you Mateo.' ), false ),
		array( 'events-and-office-hours', 17, 'Portfolio critique night: sign-up thread', 'Next critique night is on the last Wednesday of the month. Reply with a link and what feedback you want, and we will go through as many as we can.', array( 'Count me in, link coming tonight.', 'Can I join just to listen?', 'Of course, listeners are always welcome.' ), false ),
		array( 'events-and-office-hours', 17, 'Recap: our Lisbon meetup', 'Twenty-two people, two short talks and a lot of pastel de nata. Slides and photos are inside, and the next date is already set.', array( 'Wish I could have been there.', 'Great talks, thanks for organising.' ), false ),
		array( 'events-and-office-hours', 14, 'Office hours: learning design, ask me anything', 'I will be online on Friday for an hour to answer questions about building courses people finish. Post questions here in advance.', array( 'How long should a single lesson be?', 'Looking forward to this.' ), false ),
		array( 'events-and-office-hours', 9, 'Photo walk this Saturday, all levels welcome', 'We meet at the old harbour at 9:00 and walk for two hours. Bring any camera, a phone is perfect.', array( 'See you there!', 'Is it fine to bring a friend?', 'Yes, the more the merrier.' ), false ),
		array( 'site-feedback', 16, 'Code blocks are hard to read in dark mode', 'The code background and text are very close in dark mode. Screenshot inside.', array( 'Can confirm, same on my laptop.', 'Thanks for reporting, we are on it.' ), false ),
		array( 'site-feedback', 8, 'Notification emails could be shorter', 'The reply emails repeat the whole thread. Just the new reply and a link would be easier to read on a phone.', array( 'Agree, especially on mobile.', 'Plus one from me.' ), false ),
		array( 'site-feedback', 19, 'Image uploads are slow on mobile data', 'Uploading a photo from my phone takes a long time on a weak signal. Could images be resized before upload?', array( 'Same here when travelling.', 'Good idea, resizing first would help a lot.' ), false ),
		array( 'site-feedback', 0, 'The new space cards look great', 'The cards on the community page are much easier to scan. Showing members and last activity was a nice touch.', array( 'Agreed, much cleaner.', 'Thanks Alex, glad it helps.' ), false ),
		array( 'wins-and-milestones', 16, 'Got my first raise, thanks to this forum', 'I used the advice from the negotiation thread in Career Corner and it worked. Thank you all.', array( 'Congratulations, well deserved!', 'So happy for you, Chloe.', 'This is why this place is great.' ), false ),
		array( 'wins-and-milestones', 15, 'Our bakery app hit 100 paying customers', 'Two years in, one hundred bakeries pay for the app. Small numbers, but every one of them uses it daily.', array( 'Huge milestone, congratulations!', 'What made the biggest difference?', 'Talking to bakers every single week.' ), false ),
		array( 'wins-and-milestones', 5, 'My game is finally out', 'Three years of weekends and it is live. A tiny pixel art puzzle game about a lighthouse keeper.', array( 'Downloading it tonight!', 'The trailer looks lovely.' ), false ),
		array( 'wins-and-milestones', 10, 'Our docs project passed 500 contributors', 'Most of them started with a typo fix. Thank you to everyone here who helped review pull requests.', array( 'Docs first pays off. Congratulations!', 'Proud to be one of the 500.' ), false ),
	),
